{"content": "from decimal import Decimal
from typing import List

from pydantic import BaseModel


class PricePoint(BaseModel):
    sku: str
    price: Decimal
    discount: Decimal = Decimal("0")


class PriceList(BaseModel):
    currency: str
    points: List[PricePoint]


def price_list_json(pl: PriceList) -> str:
    # Pydantic v2 serializes Decimal as a string by default (v1 emitted a float).
    # Use model_dump_json(); pass a field serializer if the old float output must be preserved.
    return pl.model_dump_json()
